#!/system/bin/sh
# VirgoXbeast-Perf Protected Core
_d(){ if command -v base64 >/dev/null 2>&1;then printf '%s' "$1"|base64 -d;elif [ -x /data/adb/magisk/busybox ];then printf '%s' "$1"|/data/adb/magisk/busybox base64 -d;elif [ -x /data/adb/ksu/bin/busybox ];then printf '%s' "$1"|/data/adb/ksu/bin/busybox base64 -d;elif [ -x /data/adb/ap/bin/busybox ];then printf '%s' "$1"|/data/adb/ap/bin/busybox base64 -d;elif command -v toybox >/dev/null 2>&1;then printf '%s' "$1"|toybox base64 -d;elif command -v busybox >/dev/null 2>&1;then printf '%s' "$1"|busybox base64 -d;fi; }
_P=""
eval "$(_d "$_P")"
